using System.ComponentModel;
using System.Net;
using System.Text;
using System.Text.RegularExpressions;
using Microsoft.Extensions.AI;
using Microsoft.Agents.AI.ChatCompletion;
using OpenAI;

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

IChatClient chatClient = new OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

var notepad = new Notepad();

var tools = new AITool[]
{
    AIFunctionFactory.Create(WebSearch.SearchAsync),
    AIFunctionFactory.Create(WebSearch.FetchPageAsync),
    AIFunctionFactory.Create(notepad.AddNote),
    AIFunctionFactory.Create(notepad.GetAllNotes),
};

var agent = new ChatClientAgent(
    chatClient,
    name: "ResearchAgent",
    instructions: """
        You are a research agent. Your job is to thoroughly research a topic the user
        asks about by searching the web, reading relevant pages, and taking notes on
        key findings. Follow this workflow:

        1. Search the web for the topic using multiple varied queries.
        2. Fetch and read the most relevant pages from the search results.
        3. Take structured notes on important facts, data, and insights you find.
        4. After gathering enough information, review your notes and provide a
           comprehensive summary with key findings, organized by theme.

        Always take notes before summarizing so you don't lose important details.
        Cite sources where possible.
        """);

Console.WriteLine("=== Research Agent ===");
Console.Write("Enter a topic to research: ");
var topic = Console.ReadLine()?.Trim();

if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

var history = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}"),
};

var options = new AgentInvokeOptions
{
    ModelOptions = new ChatOptions
    {
        Tools = [.. tools],
        Temperature = 0f,
        MaxOutputTokens = 4096,
    },
    MaximumIterations = 15,
};

await foreach (var response in agent.InvokeStreamingAsync(history, options))
{
    if (response.Role == ChatRole.Assistant && !string.IsNullOrEmpty(response.Text))
    {
        Console.Write(response.Text);
    }
}

Console.WriteLine();

// --- Tool definitions ---

public static partial class WebSearch
{
    private static readonly HttpClient s_http = new()
    {
        Timeout = TimeSpan.FromSeconds(15),
        DefaultRequestHeaders =
        {
            { "User-Agent", "Mozilla/5.0 (compatible; ResearchAgent/1.0)" },
            { "Accept", "text/html" },
        },
    };

    [Description("Search the web for a query. Returns a list of result titles and URLs.")]
    public static async Task<string> SearchAsync(
        [Description("The search query string")] string query)
    {
        try
        {
            var encoded = WebUtility.UrlEncode(query);
            var url = $"https://html.duckduckgo.com/html/?q={encoded}";
            var html = await s_http.GetStringAsync(url);

            var results = new StringBuilder();
            int count = 0;

            foreach (Match match in ResultPattern().Matches(html))
            {
                if (count >= 8) break;

                var linkHref = WebUtility.HtmlDecode(match.Groups[1].Value);
                var title = WebUtility.HtmlDecode(StripHtml(match.Groups[2].Value));

                // DuckDuckGo redirects through their own URL; extract the actual URL
                var actualUrl = ExtractRedirectUrl(linkHref) ?? linkHref;

                if (actualUrl.Contains("duckduckgo.com")) continue;

                count++;
                results.AppendLine($"{count}. {title}");
                results.AppendLine($"   URL: {actualUrl}");
                results.AppendLine();
            }

            return count > 0
                ? results.ToString()
                : "No results found. Try a different query.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }

    [Description("Fetch the text content of a web page given its URL.")]
    public static async Task<string> FetchPageAsync(
        [Description("The full URL of the page to fetch")] string url)
    {
        try
        {
            var html = await s_http.GetStringAsync(url);
            var text = StripHtml(html);

            // Collapse whitespace and limit length
            text = CollapseWhitespace().Replace(text, " ").Trim();
            if (text.Length > 6000)
                text = text[..6000] + "\n\n[Content truncated]";

            return string.IsNullOrWhiteSpace(text)
                ? "Page returned no readable content."
                : text;
        }
        catch (Exception ex)
        {
            return $"Failed to fetch page: {ex.Message}";
        }
    }

    private static string StripHtml(string html)
    {
        html = ScriptStylePattern().Replace(html, " ");
        html = TagPattern().Replace(html, " ");
        html = WebUtility.HtmlDecode(html);
        return html;
    }

    private static string? ExtractRedirectUrl(string href)
    {
        var match = UdducPattern().Match(href);
        return match.Success ? WebUtility.UrlDecode(match.Groups[1].Value) : null;
    }

    [GeneratedRegex(@"<script[^>]*>[\s\S]*?</script>|<style[^>]*>[\s\S]*?</style>",
        RegexOptions.IgnoreCase)]
    private static partial Regex ScriptStylePattern();

    [GeneratedRegex(@"<[^>]+>")]
    private static partial Regex TagPattern();

    [GeneratedRegex(@"\s{2,}")]
    private static partial Regex CollapseWhitespace();

    [GeneratedRegex(@"uddg=([^&]+)")]
    private static partial Regex UdducPattern();

    [GeneratedRegex(
        @"<a[^>]+class=""result__a""[^>]+href=""([^""]+)""[^>]*>(.*?)</a>",
        RegexOptions.IgnoreCase | RegexOptions.Singleline)]
    private static partial Regex ResultPattern();
}

public class Notepad
{
    private readonly List<(string Title, string Content)> _notes = [];

    [Description("Save a research note with a title and content. Use this to record key findings.")]
    public string AddNote(
        [Description("Short title for the note")] string title,
        [Description("The note content with facts and details")] string content)
    {
        _notes.Add((title, content));
        return $"Note saved: \"{title}\" (total notes: {_notes.Count})";
    }

    [Description("Retrieve all saved research notes to review before writing a summary.")]
    public string GetAllNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        var sb = new StringBuilder();
        for (int i = 0; i < _notes.Count; i++)
        {
            sb.AppendLine($"--- Note {i + 1}: {_notes[i].Title} ---");
            sb.AppendLine(_notes[i].Content);
            sb.AppendLine();
        }
        return sb.ToString();
    }
}

